Method.Implementation:
  	$$$TRACE("Entering IHC.ITF.ITFCOMMON.Operation.FilePassthroughOperation...")
  	$$$TRACE("pRequest.Protocol / Folder: "_pRequest.Protocol _" / "_pRequest.Folder)

	$$$TRACE("Append Protocol, Folder to file path...")
	set origFilePath = ..Adapter.FilePath
  	set ..Adapter.FilePath = ..Adapter.FilePath  _ pRequest.Protocol _"/" _ pRequest.Folder _"/"

  	$$$TRACE("Adapter.FilePath: "_..Adapter.FilePath)

  	if ('##class(%File).DirectoryExists(..Adapter.FilePath))
  	{
	  	set tSC = ##class(%File).CreateDirectoryChain(..Adapter.FilePath)
	  	if ($$$ISERR(tSC))
	  	{
		  	set ..Adapter.FilePath = origFilePath
		  	return tSC
	  	}
  	}

  	set tSC=##super(pRequest,.pResponse)

  	set ..Adapter.FilePath = origFilePath


  	Quit tSC
